<?php
session_start();
require_once __DIR__ . '/config/database.php';
if (empty($_SESSION['demo_limpio'])) { try { $pdo->prepare("UPDATE empresas SET nombre='GIUBOL' WHERE LOWER(TRIM(nombre))='giubol demo'")->execute(); $pdo->prepare("UPDATE clientes SET correo=REPLACE(correo,'@demo.com','@ejemplo.com') WHERE correo LIKE '%@demo.com'")->execute(); } catch (Exception $e) {} $_SESSION['demo_limpio']=1; }
$empresa = $pdo->query("SELECT * FROM empresas WHERE activo=1 ORDER BY id_empresa ASC LIMIT 1")->fetch() ?: ['id_empresa'=>1,'nombre'=>'GIUBOL','telefono'=>'','correo'=>'','ciudad'=>'','estado'=>''];
$empresa['nombre']=trim(preg_replace('/\s+/',' ',preg_replace('/\bdemo\b/i','',(string)$empresa['nombre']))) ?: 'GIUBOL';
$id_empresa=(int)$empresa['id_empresa'];
if (empty($_SESSION['giubol_public_csrf'])) $_SESSION['giubol_public_csrf']=bin2hex(random_bytes(32));
$token=$_SESSION['giubol_public_csrf'];
$st=$pdo->prepare("SELECT id_producto,nombre,tipo,unidad,precio_venta,stock FROM productos WHERE id_empresa=? AND activo=1 ORDER BY nombre");$st->execute([$id_empresa]);$productos=$st->fetchAll();
$success=isset($_GET['enviado']) && $_GET['enviado']==='1';$error='';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$tipoInicial=isset($_GET['tipo']) && in_array($_GET['tipo'],['Construccion','Remodelacion','Ampliacion','Diseno','Instalacion','Otro'],true)?$_GET['tipo']:'Construccion';
$productoInicial=isset($_GET['producto'])?(int)$_GET['producto']:0;
$configInicial='';
if (!empty($_GET['config'])) {
    $cfg=json_decode((string)$_GET['config'], true);
    if (is_array($cfg)) {
        $configInicial="Configuración del visualizador GIUBOL:\n";
        foreach (['espacio'=>'Espacio','estilo'=>'Estilo','muros'=>'Acabado de muros','piso'=>'Acabado de piso','color'=>'Color de acento','ancho'=>'Ancho aproximado (m)','largo'=>'Largo aproximado (m)','area'=>'Área aproximada (m²)','material'=>'Material seleccionado'] as $key=>$label) {
            if (isset($cfg[$key]) && is_scalar($cfg[$key])) {
                $configInicial .= $label.': '.substr(trim((string)$cfg[$key]),0,180)."\n";
            }
        }
        $configInicial .= "\nDescribe cualquier otro detalle de tu proyecto: ";
    }
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($token,(string)($_POST['csrf']??''))) throw new RuntimeException('La sesión del formulario venció. Recarga la página e inténtalo de nuevo.');
  if(!empty($_POST['website'])) throw new RuntimeException('No fue posible procesar la solicitud.');
  $nombre=trim((string)($_POST['nombre']??''));$apellidos=trim((string)($_POST['apellidos']??''));$correo=trim((string)($_POST['correo']??''));$telefono=trim((string)($_POST['telefono']??''));$ciudad=trim((string)($_POST['ciudad']??''));$empresaCliente=trim((string)($_POST['empresa_cliente']??''));$etapa=trim((string)($_POST['etapa']??'Estoy explorando ideas'));$proyecto=trim((string)($_POST['proyecto']??''));$descripcion=trim((string)($_POST['descripcion']??''));$tipo=trim((string)($_POST['tipo_proyecto']??'Otro'));$cantidades=$_POST['cantidad']??[];$seleccionados=$_POST['productos']??[];
  if($nombre===''||$telefono===''||$proyecto===''||strlen($descripcion)<12) throw new RuntimeException('Completa nombre, teléfono, nombre del proyecto y una descripción de al menos 12 caracteres.');
  if($correo!==''&&!filter_var($correo,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Escribe un correo electrónico válido.');
  if(!in_array($tipo,['Construccion','Remodelacion','Ampliacion','Diseno','Instalacion','Otro'],true))$tipo='Otro';
  $catalogo=[];if(is_array($seleccionados)){ $ids=array_values(array_unique(array_filter(array_map('intval',$seleccionados),fn($v)=>$v>0))); if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT id_producto,nombre,tipo,unidad,precio_venta FROM productos WHERE id_empresa=? AND activo=1 AND id_producto IN ($marks)");$q->execute(array_merge([$id_empresa],$ids));foreach($q->fetchAll() as $p){$qty=isset($cantidades[$p['id_producto']])?(float)$cantidades[$p['id_producto']]:1;$qty=max(0.01,min(100000,$qty));$catalogo[]=['id'=>(int)$p['id_producto'],'nombre'=>$p['nombre'],'unidad'=>$p['unidad'],'precio'=>(float)$p['precio_venta'],'cantidad'=>$qty,'importe'=>(float)$p['precio_venta']*$qty];}}}
  $subtotal=0;foreach($catalogo as $linea)$subtotal+=$linea['importe'];$iva=round($subtotal*.16,2);$total=$subtotal+$iva;
  $pdo->beginTransaction();
  $q=$pdo->prepare("INSERT INTO clientes (id_empresa,nombre,apellidos,empresa_cliente,telefono,correo,ciudad,estado,tipo_cliente,notas) VALUES (?,?,?,?,?,?,?,?,?,?)");$q->execute([$id_empresa,$nombre,$apellidos,$empresaCliente,$telefono,$correo,$ciudad,$empresa['estado']??'', $empresaCliente!==''?'Empresa':'Particular','Solicitud recibida desde el portal público GIUBOL.']);$idCliente=(int)$pdo->lastInsertId();
  $q=$pdo->prepare("INSERT INTO proyectos (id_empresa,id_cliente,nombre,descripcion,tipo_proyecto,estado,presupuesto) VALUES (?,?,?,?,?,'Cotizacion',?)");$q->execute([$id_empresa,$idCliente,$proyecto,$descripcion,$tipo,$total]);$idProyecto=(int)$pdo->lastInsertId();
  $folio='WEB-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
  $notas="SOLICITUD RECIBIDA DESDE EL PORTAL PÚBLICO. Pendiente de revisión por el equipo GIUBOL.\nEtapa del cliente: ".$etapa."\nUbicación del proyecto: ".$ciudad."\nEmpresa: ".$empresaCliente."\nDescripción: ".$descripcion;
  $q=$pdo->prepare("INSERT INTO cotizaciones (id_empresa,id_cliente,id_proyecto,folio,fecha,vigencia,estado,subtotal,iva,total,notas) VALUES (?,?,?,?,?,DATE_ADD(CURDATE(), INTERVAL 15 DAY),'Borrador',?,?,?,?)");$q->execute([$id_empresa,$idCliente,$idProyecto,$folio,date('Y-m-d'),$subtotal,$iva,$total,$notas]);$idCot=(int)$pdo->lastInsertId();
  if($catalogo){$q=$pdo->prepare("INSERT INTO detalle_cotizaciones (id_cotizacion,id_producto,descripcion,cantidad,precio,importe) VALUES (?,?,?,?,?,?)");foreach($catalogo as $l)$q->execute([$idCot,$l['id'],$l['nombre'].' ('.$l['unidad'].')',$l['cantidad'],$l['precio'],$l['importe']]);}
  else{$q=$pdo->prepare("INSERT INTO detalle_cotizaciones (id_cotizacion,id_producto,descripcion,cantidad,precio,importe) VALUES (?,NULL,?,1,0,0)");$q->execute([$idCot,'Revisión de alcance y elaboración de propuesta']);}
  $pdo->commit();unset($_SESSION['giubol_public_csrf']);header('Location: solicitar.php?enviado=1&folio='.rawurlencode($folio));exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'No pudimos registrar tu solicitud. Verifica los datos e inténtalo nuevamente.';}
}
