tion></div></main><footer class="site-footer quote-footer"><div class="container footer-bottom"><span>© <?= date('Y') ?> <?= e($empresa['nombre']) ?></span><a href="auth/login.php">Acceso empresas ↗</a></div></footer>
<script>const fmt=new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'});function calc(){let total=0;document.querySelectorAll('.product-select').forEach(row=>{const check=row.querySelector('input[type=checkbox]');const qty=row.querySelector('input[type=number]');qty.disabled=!check.checked;row.classList.toggle('selected',check.checked);if(check.checked)total+=Number(check.dataset.price||0)*Math.max(.01,Number(qty.value||1));});const el=document.getElementById('estimateTotal');if(el)el.textContent=fmt.format(total)}document.querySelectorAll('.product-select input').forEach(i=>i.addEventListener('change',calc));document.querySelectorAll('.product-select input[type=number]').forEach(i=>i.addEventListener('input',calc));calc();</script></body></html>
